SELECT ROW_NUMBER() OVER () AS week_id , rpt03_person_id AS person_id , rpt03_week_start_date AS week_start_date , rpt03_week_close_date AS week_close_date , rpt03_org_nm AS org_name , rpt03_person_nm AS person_name , rpt03_org_id AS org_code_id , rpt03_org_cd AS org_cd , rpt03_confirmer_id AS confirmer_id , rpt03_confirmer AS confirmer , rpt03_confirmer_org_nm AS confirmer_org_name , rpt03_confirm_date_str AS confirm_date_str , rpt03_confirm_note AS confirm_note , rpt03_confirm_yn = 'true' AS confirm_yn FROM (SELECT rpt03_company_id , rpt03_person_id , rpt03_week_start_date , rpt03_week_close_date , f_get_empTrans(rpt03_person_id, rpt03_week_start_date, 'org_code_nm') AS rpt03_org_nm , f_emp_kor_nm(rpt03_person_id) AS rpt03_person_nm , CAST(f_get_empTrans(rpt03_person_id, rpt03_week_start_date, 'org_code_id') as numeric) AS rpt03_org_id , f_get_empTrans(rpt03_person_id, rpt03_week_start_date, 'org_cd') AS rpt03_org_cd , (SELECT rpt04_confirmer_id FROM rpt04_week_confirm WHERE rpt04_week_start_date = rpt03_week_start_date AND rpt04_person_id = rpt03_person_id AND rpt04_company_id = rpt03_company_id) AS rpt03_confirmer_id , (SELECT f_emp_kor_nm(rpt04_confirmer_id) FROM rpt04_week_confirm WHERE rpt04_week_start_date = rpt03_week_start_date AND rpt04_person_id = rpt03_person_id AND rpt04_company_id = rpt03_company_id) AS rpt03_confirmer , (SELECT f_get_empTrans(rpt04_confirmer_id, rpt04_week_start_date, 'org_code_nm') FROM rpt04_week_confirm WHERE rpt04_week_start_date = rpt03_week_start_date AND rpt04_person_id = rpt03_person_id AND rpt04_company_id = rpt03_company_id) AS rpt03_confirmer_org_nm , (SELECT to_char(rpt04_confirm_datetime, 'YYYY-MM-DD HH24:MI:SS') FROM rpt04_week_confirm WHERE rpt04_week_start_date = rpt03_week_start_date AND rpt04_person_id = rpt03_person_id AND rpt04_company_id = rpt03_company_id) AS rpt03_confirm_date_str , (SELECT rpt04_note FROM rpt04_week_confirm WHERE rpt04_week_start_date = rpt03_week_start_date AND rpt04_person_id = rpt03_person_id AND rpt04_company_id = rpt03_company_id) AS rpt03_confirm_note , COALESCE((SELECT CASE WHEN rpt04_confirmer_id IS null THEN 'false' ELSE 'true' END FROM rpt04_week_confirm WHERE rpt04_week_start_date = rpt03_week_start_date AND rpt04_person_id = rpt03_person_id AND rpt04_company_id = rpt03_company_id), 'false') AS rpt03_confirm_yn FROM rpt03_week WHERE rpt03_week_start_date = #{startDate}::date AND rpt03_company_id = #{companyId} AND rpt03_fix_yn = 'true' GROUP BY rpt03_company_id, rpt03_person_id, rpt03_week_start_date, rpt03_week_close_date) t WHERE 1=1
AND rpt03_confirm_yn = 'false'
AND rpt03_org_id = #{orgCodeId}

SELECT f_emp_kor_nm(rpt04_confirmer_id)                                              AS confirmer_name
     , f_get_empTrans(rpt04_confirmer_id, rpt04_week_start_date, 'org_code_nm')      AS confirmer_org_name
     , to_char(rpt04_confirm_datetime, 'YYYY-MM-DD HH24:MI:SS')                      AS confirm_date_str
  FROM rpt04_week_confirm
 WHERE rpt04_company_id = #{companyId}
   AND rpt04_person_id = #{personId}
   AND rpt04_week_start_date = #{startDate}::date
   AND rpt04_confirmer_id = #{confirmerId}
 LIMIT 1

mapper.update:
WITH upsert AS
(
UPDATE rpt04_week_confirm
   SET rpt04_note            = #{confirmNote}
 WHERE rpt04_company_id      = #{companyId}
   AND rpt04_person_id       = #{personId}
   AND rpt04_week_start_date = #{startDate}::date
 RETURNING *
)
INSERT INTO rpt04_week_confirm
     ( rpt04_week_confirm_id, rpt04_company_id, rpt04_person_id, rpt04_week_start_date, rpt04_note )
SELECT f_create_seq(), #{companyId}, #{personId}, #{startDate}::date, #{confirmNote}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

UPDATE rpt04_week_confirm
   SET rpt04_confirmer_id     = null
     , rpt04_confirm_datetime = null
     , rpt04_note             = #{confirmNote}
 WHERE rpt04_company_id       = #{companyId}
   AND rpt04_person_id        = #{personId}
   AND rpt04_week_start_date  = #{startDate}::date
